/* Northstar owner workspace — fictional, local interactive prototype. */
const adminState = {
  planVersion:3, weekly:2, monthly:8, basis:'reservation', late:'count', noShow:'count',
  scheduleChanged:false, occurrenceCancelled:false, timetableDay:9, rosterDay:9, selectedClassId:'beginner-muay', selectedMemberId:'maya', trial:'attended', guardianBooking:true,
  rank:'Yellow belt', rankMode:'prerequisites', peopleFilter:'all', correction:false,
  payment:'failed', cardUpdated:false, refund:'none', refundAmount:40, credit:0, disputeReviewed:false, disputeResolved:false, billingFilter:'all',
  cancellation:'none', waiveRenewal:false, freeze:'none', waiverPublished:false,
  migrationReviewed:false, reauthorized:false, dryRun:false, ownerAck:false, activated:false,
  exportReady:false, exportReceipt:false, exitPlanned:false, supportAccess:false,
  incident:'investigating', deliveryRetried:false, audit:[],
  fallbackMember:{booked:false,bookingDate:'fri',bookingClassId:'beginner-muay',attended:false,waiverSigned:false}
};
root.addEventListener('change',event=>{
 if(event.target.id!=='a-timetable-day')return;
 const day=aDayNumber(event.target.value);
 if(Number.isInteger(day)&&day>=9&&day<=39){adminState.timetableDay=day;render();saveSelection();}
});
const aMember = () => typeof memberState !== 'undefined' ? memberState : adminState.fallbackMember;
const aMayaBookingPending = () => aMember().bookingPending&&aMember().pendingOperation?.profile==='adult';
const aTodayBooked = () => aMember().booked && aMember().bookingDate==='fri' && (aMember().bookingClassId||'beginner-muay')==='beginner-muay';
const aRosterClass = () => csOccurrence(adminState.selectedClassId,adminState.rosterDay)||(adminState.selectedClassId==='beginner-muay'&&adminState.rosterDay===16?adminState.cancelledClassSnapshot:null)||csSeries(adminState.selectedClassId,adminState.rosterDay)||demoClass('beginner-muay');
const aBookingDay = day => ({fri:9,sat:10,sun:11,mon:12,'next-mon':12}[day]||null);
const aDayKey = day => ({9:'fri',10:'sat',11:'sun',12:'next-mon'}[day]||null);
function aDayNumber(value){const date=csDate(value);return date?Math.round((Date.parse(date+'T00:00:00Z')-Date.UTC(2026,9,1))/86400000)+1:NaN;}
const aDayLabel = value => {const date=csDate(value);return date?new Date(date+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).replace(',',''):'Choose a date';};
const aOccurrenceBooked = (item,day) => !!aMember().booked&&aBookingDay(aMember().bookingDate)===day&&(aMember().bookingClassId||'beginner-muay')===item.id;
const aRosterBooked = () => aOccurrenceBooked(aRosterClass(),adminState.rosterDay);
const aRosterSample = () => adminState.rosterDay===9&&aRosterClass().id==='beginner-muay';
const aTimetableException = (item,day=adminState.timetableDay) => item.id==='beginner-muay'&&day===16;
const aOccurrenceCancelled = (item,day) => aTimetableException(item,day)&&adminState.occurrenceCancelled;
const aClassSeats = (item,day) => {const current=csOccurrence(item.id,day);return `${current?csBooked(item.id,day):0} / ${current?.capacity||item.capacity}`;};
const aRosterSeats = () => aClassSeats(aRosterClass(),adminState.rosterDay);
const aTimetableDay = () => aDayLabel(adminState.timetableDay);
const aScheduledRange = (item,day=adminState.timetableDay) => demoClassRange(csOccurrence(item.id,day)||item);
const aScheduledCoach = (item,day=adminState.timetableDay) => classCoachLabel(csOccurrence(item.id,day)||item,'owner');
const aRosterSubtitle = () => `${aDayLabel(adminState.rosterDay)} · ${aScheduledRange(aRosterClass(),adminState.rosterDay)} · ${aRosterClass().space} · ${aScheduledCoach(aRosterClass(),adminState.rosterDay)}`;
function aOpenRoster(classId='beginner-muay',value=9){const day=aDayNumber(value);if(!csSeries(classId)||!Number.isInteger(day)||day<9||day>39)return;if(!csOccurrence(classId,day)&&!(classId==='beginner-muay'&&day===16&&adminState.occurrenceCancelled))return;adminState.selectedClassId=classId;adminState.rosterDay=day;adminState.timetableDay=day;navigate('a-roster');}
const aMemberBookingLabel = () => {const day=aBookingDay(aMember().bookingDate)||9,item=csOccurrence(aMember().bookingClassId||'beginner-muay',day)||csSeries(aMember().bookingClassId,day)||demoClass('beginner-muay');return `${item.title} · ${aDayLabel(day)} · ${demoClassRange(item)}`;};
const aMayaUsage = () => {
 const m=aMember(),caps=memberLimits('adult'),limit=uiState.scenario==='limit',funded=m.funding!=='pack',late=m.lateConsumed?1:0;
 const thisWeekBooked=m.booked&&['fri','sat','sun'].includes(m.bookingDate);
 const used=(limit?2:1)+(['fri','sat','sun'].includes(m.bookingDate)?late:0)+(thisWeekBooked&&m.attended&&funded?1:0),held=thisWeekBooked&&!m.attended&&funded?1:0;
 const monthUsed=(uiState.scenario==='monthly'?8:limit?5:4)+late+(m.attended&&funded?1:0),monthHeld=m.booked&&!m.attended&&funded?1:0;
 return {used,held,left:caps.weekly===null?null:Math.max(0,caps.weekly-used-held),monthUsed,monthHeld,monthLeft:caps.monthly===null?null:Math.max(0,caps.monthly-monthUsed-monthHeld)};
};
const aMayaAvailable = (usage=aMayaUsage(),after=0) => {
 const parts=[];
 if(usage.left!==null)parts.push(`${Math.max(0,usage.left-after)} available this week`);
 if(usage.monthLeft!==null)parts.push(`${Math.max(0,usage.monthLeft-after)} available this billing month`);
 return parts.join(' · ')||'Unlimited classes';
};
const aMayaTerms = () => {
 const caps=memberLimits('adult'),parts=[];
 if(caps.weekly!==null)parts.push(`${caps.weekly} per training week`);
 if(caps.monthly!==null)parts.push(`${caps.monthly} per billing month`);
 return parts.join(' · ')||'Unlimited classes';
};
const aAccessProblem = () => {const m=aMember();return m.membershipEnded||m.cancellationEffective?'The membership has ended.':m.freezeEffective?'The membership is currently frozen.':m.payment==='restricted'?'The membership is restricted because of an unpaid invoice.':m.archived?'The member record is archived.':'';};
const aVal = (id,fallback='') => document.getElementById(id)?.value ?? fallback;
const aChecked = id => !!document.getElementById(id)?.checked;
const aMoney = value => new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',currencyDisplay:'code'}).format(value).replace(/\s+/g,'\u202f');
const aLog = (action,object,reason='') => adminState.audit.unshift({action,object,reason,time:'9 Oct · 17:42',actor:'Alex Morgan · owner'});
const aDone = message => {closeDialog();render();toast(message);};
const aModal = (title,body,action,label='Confirm',kind='primary') => showDialog(title,body,`${act('Back','a-close','ghost')}${action?act(label,action,kind):''}`);
const aDates = () => ['5–11 Oct','12–18 Oct','19–25 Oct','26 Oct–1 Nov','2–4 Nov'];
const aRenewals = () => adminState.freeze==='scheduled' ? [['5 Dec 2026',aMoney(149),'Final renewal']] : [['5 Nov 2026',adminState.waiveRenewal?aMoney(0):aMoney(149),adminState.waiveRenewal?'Owner waiver':'Renewal'],['5 Dec 2026',aMoney(149),'Final renewal']];
const aStatus = (value,good='success') => badge(value,value==='Pending'?'warning':good);
const aAuditTable = () => table(['When / actor','Action','Record','Reason'],[...adminState.audit,{time:'9 Oct · 16:18',actor:'Jordan Lee · coach',action:'Attendance corrected',object:'ATT-781 · 8 Oct',reason:'Wrong status selected; correction recorded in the original period'},{time:'9 Oct · 15:51',actor:'Alex Morgan · owner',action:'Guardian grant verified',object:'REL-104 · Ava Chen',reason:'Signing authority evidence reviewed'}].slice(0,6).map(x=>[`${x.time}<br><span class="hl-muted hl-small">${esc(x.actor)}</span>`,esc(x.action),esc(x.object),esc(x.reason||'—')]));

